<?php
if (!defined('_GNUBOARD_')) exit;
require_once __DIR__.'/_common.php'; $t=reflammer_wiki_table('setting'); $tt=reflammer_wiki_table('tag'); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST') { check_admin_token(); if(($_POST['op']??'')==='moderators') { $ids=preg_split('/[\r\n,]+/',(string)($_POST['moderators']??'')); $ids=array_unique(array_filter(array_map('trim',$ids))); $val=sql_real_escape_string(implode("\n",$ids)); sql_query("REPLACE INTO `{$t}` (ws_key,ws_value) VALUES ('moderators','{$val}')",false); $msg='운영진 목록을 저장했습니다.'; } elseif(($_POST['op']??'')==='tag') { $name=trim(ltrim(strip_tags((string)($_POST['tag']??'')),'#')); if($name!=='')sql_query("INSERT IGNORE INTO `{$tt}` (wt_name) VALUES ('".sql_real_escape_string($name)."')",false); $msg='태그를 저장했습니다.'; } elseif(($_POST['op']??'')==='delete_tag') { sql_query("DELETE FROM `{$tt}` WHERE wt_id=".(int)($_POST['id']??0),false); $msg='추천에서 제거했습니다. 이미 작성된 문서의 태그는 유지됩니다.'; } }
$r=sql_fetch("SELECT ws_value FROM `{$t}` WHERE ws_key='moderators'");
?>
<?php if($msg)echo '<p class="local_desc02">'.reflammer_wiki_e($msg).'</p>'; ?><section class="tbl_frm01 tbl_wrap"><h2>지정 운영진</h2><p>한 줄에 회원 아이디 하나씩 입력하세요. 최고관리자는 항상 운영 권한을 가집니다.</p><form method="post"><input type="hidden" name="token" value="<?php echo get_admin_token(); ?>"><input type="hidden" name="op" value="moderators"><textarea name="moderators" rows="6" style="width:100%"><?php echo reflammer_wiki_e($r['ws_value']??''); ?></textarea><button class="btn_submit">저장</button></form></section>
<section class="tbl_frm01 tbl_wrap"><h2>추천 태그 사전</h2><form method="post"><input type="hidden" name="token" value="<?php echo get_admin_token(); ?>"><input type="hidden" name="op" value="tag"><input name="tag" required placeholder="공식"><button class="btn_submit">태그 추가</button></form><ul><?php $rs=sql_query("SELECT * FROM `{$tt}` ORDER BY wt_name"); while($tag=sql_fetch_array($rs)): ?><li style="margin:8px 0">#<?php echo reflammer_wiki_e($tag['wt_name']); ?><form method="post" style="display:inline"><input type="hidden" name="token" value="<?php echo get_admin_token(); ?>"><input type="hidden" name="op" value="delete_tag"><input type="hidden" name="id" value="<?php echo (int)$tag['wt_id']; ?>"><button class="btn">추천에서 제거</button></form></li><?php endwhile; ?></ul></section>
